const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Remove the cart item
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0012'\").run();

// Update the cart: remove item from item_ids_json, recalculate subtotal and total
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_fbab7801'\").get();
const itemIds = JSON.parse(cart.item_ids_json).filter(id => id !== 'CI-0012');

// Recalculate subtotal from remaining items
const remainingItems = db.prepare(\"SELECT ci.*, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_fbab7801'\").all();
const newSubtotal = remainingItems.reduce((sum, item) => sum + item.price * item.quantity, 0);
const newTotal = newSubtotal + cart.shipping_cost - cart.discount_amount - cart.loyalty_discount + cart.gift_wrap_fee;

db.prepare(\"UPDATE carts SET item_ids_json = ?, subtotal = ?, total = ? WHERE cart_id = 'CART-user_fbab7801'\").run(
  JSON.stringify(itemIds),
  newSubtotal,
  newTotal
);

// Verify
const updatedCart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_fbab7801'\").get();
const updatedItems = db.prepare(\"SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_fbab7801'\").all();
console.log('Updated cart:', JSON.stringify(updatedCart, null, 2));
console.log('Remaining items:', JSON.stringify(updatedItems, null, 2));
"

