  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  const shipCols = cols.filter(c => c.name.toLowerCase().includes('ship'));
  if (shipCols.length > 0) {
    console.log(t.name + ':', shipCols.map(c => c.name));
  }
}
